import numpy as np
import itertools

def task_func(matrix):
    arr = np.asarray(matrix)

    if arr.ndim != 2:
        raise ValueError("Input must be a 2D numeric array.")

    if not np.issubdtype(arr.dtype, np.number):
        try:
            arr = np.asarray(matrix, dtype=float)
        except Exception as exc:
            raise TypeError("Input must contain numeric values.") from exc

        if arr.ndim != 2:
            raise ValueError("Input must be a 2D numeric array.")

    sorted_values = np.sort(arr, axis=None)

    unique_combinations = []
    seen = set()
    for combo in itertools.combinations(sorted_values.tolist(), 2):
        if combo not in seen:
            seen.add(combo)
            unique_combinations.append(combo)

    return sorted_values, unique_combinations
